'use strict';
const naSchool={data:null,trip:null,view:'today',date:'',busy:false,error:''};
const schoolButton=(action,label,extra='',primary=false)=>`<button type="button" data-school-action="${action}" class="${primary?'primary':''}" ${extra}>${esc(label)}</button>`;
function schoolReset(){naSchool.data=null;naSchool.trip=null;naSchool.date='';naSchool.view='today';naSchool.error=''}
function schoolView(){if(!naSchool.data)return pageHead('Chamadas',naSchool.error||'Carregando as viagens…',schoolButton('refresh','Atualizar'));const d=naSchool.data;if(naSchool.trip)return schoolCallView();return `${pageHead('Chamadas','Viagens e presença dos alunos, por horário e sentido.',d.canManage?schoolButton('new','Nova viagem','',true):'')}<div class="tabs school-tabs">${[['today','Viagens do dia'],...(d.canManage?[['routes','Linhas e alunos']]:[]),['history','Histórico']].map(([v,l])=>`<button data-school-action="view" data-view="${v}" class="${naSchool.view===v?'active':''}">${l}</button>`).join('')}</div>${naSchool.view==='routes'?schoolRoutesView():naSchool.view==='history'?schoolHistoryView():schoolTodayView()}`}
function schoolTodayView(){const d=naSchool.data,weekday=new Date(d.date+'T12:00:00Z').getUTCDay(),items=d.routes.filter(r=>r.active&&r.weekdays.includes(weekday)),finished=d.trips.filter(t=>t.status==='done').length;return `<div class="school-summary"><span><strong>${items.length}</strong> viagens previstas</span><span><strong>${finished}</strong> concluídas</span><span>${fmt(d.date)}</span></div><div class="school-route-list">${items.map(r=>{const t=d.trips.find(t=>t.routeId===r.id);return `<section class="panel school-route"><div class="school-time">${esc(r.time)}<small>${esc(r.direction)}</small></div><div class="school-route-info"><h2>${esc(r.school)}</h2><p>${esc(r.line)} · ${r.students.length} aluno(s)</p>${r.demo?badge('pending','Demonstração'):''}<span class="help">${t?.status==='done'?'Concluída':t?'Em andamento':'Aguardando'}</span></div>${schoolButton('open',t?.status==='done'?'Ver chamada':t?'Continuar':'Iniciar viagem',`data-route="${r.id}"`,t?.status!=='done')}</section>`}).join('')||`<section class="panel"><h2>Nenhuma viagem para hoje</h2><p class="help">${d.canManage?'Cadastre uma viagem e vincule os funcionários responsáveis.':'As viagens vinculadas à sua conta aparecerão aqui.'}</p></section>`}</div>`}
function schoolRoutesView(){const d=naSchool.data;return `<p class="help">Cada viagem tem horário, sentido, dias e responsáveis próprios. Ao alterar uma lista, as chamadas já iniciadas preservam seus alunos.</p>${d.routes.filter(r=>r.active).map(r=>`<section class="panel"><div class="section-head"><div><h2>${esc(r.school)}</h2><p>${esc(r.line)} · ${esc(r.time)} · ${esc(r.direction)}</p></div>${r.demo?badge('pending','Demonstração'):''}</div><p>${r.students.length} aluno(s) · ${r.assignees.map(id=>esc(d.employees.find(e=>e.id===id)?.name||'Conta indisponível')).join(', ')||'Sem responsável vinculado'}</p><details><summary>Alunos da viagem</summary><ul>${r.students.map(s=>`<li>${esc(s.name)}</li>`).join('')}</ul></details><div class="actions">${schoolButton('edit','Editar viagem',`data-route="${r.id}"`)}${schoolButton('archive','Arquivar',`data-route="${r.id}"`)}</div></section>`).join('')||'<section class="panel"><p>Nenhuma viagem cadastrada.</p></section>'}<p class="help">Arquivar retira a viagem do itinerário e preserva as chamadas já registradas.</p>`}
function schoolHistoryView(){const d=naSchool.data;return `<section class="panel"><form id="school-history-form" class="actions"><label>Data<input type="date" name="date" value="${esc(d.date)}" max="${esc(d.today)}" required></label><button type="submit">Consultar</button></form></section>${d.trips.map(t=>{const yes=Object.values(t.marks).filter(m=>m.value==='presente').length,no=Object.values(t.marks).filter(m=>m.value==='ausente').length;return `<section class="panel"><h2>${esc(t.snapshot.school)}</h2><p>${esc(t.snapshot.line)} · ${esc(t.snapshot.time)} · ${esc(t.snapshot.direction)} · ${t.status==='done'?'Concluída':'Em aberto'}</p><p>${yes} presente(s) · ${no} ausente(s) · ${t.snapshot.students.length-yes-no} sem marcação</p>${schoolButton('review','Ver chamada',`data-trip="${t.id}"`)}</section>`}).join('')||'<section class="panel"><p>Nenhuma chamada registrada nessa data.</p></section>'}`}
function schoolCallView(){const t=naSchool.trip,r=t.snapshot,marked=Object.keys(t.marks).length,readOnly=t.status==='done'||t.date!==naSchool.data.today;return `${schoolButton('back','Voltar às viagens')}<div class="page-head school-call-head"><div><p class="school-call-label">CHAMADA · ${esc(r.direction.toUpperCase())}</p><h1>${esc(r.school)}</h1><p>${esc(r.line)} · ${esc(r.time)} · ${fmt(t.date)}</p></div>${badge('pending',t.status==='done'?'Concluída':readOnly?'Consulta do histórico':`${marked} de ${r.students.length} marcados`)}</div>${r.demo?'<p class="notice">Demonstração: alunos fictícios.</p>':''}<section class="panel school-students">${r.students.map(s=>{const m=t.marks[s.id];return `<article class="school-student"><span class="avatar" aria-hidden="true">${esc(profileInitials(s.name))}</span><div class="school-student-name"><strong>${esc(s.name)}</strong><small>${m?`${m.value==='presente'?'Presente':'Ausente'} · ${novaClock(m.at)}`:'Ainda não marcado'}</small></div>${readOnly?badge(m?.value==='presente'?'green':m?'yellow':'pending',m?.value==='presente'?'Presente':m?'Ausente':'Sem marcação'):`<div class="school-choices">${['presente','ausente'].map(v=>`<button type="button" data-school-action="mark" data-student="${s.id}" data-value="${v}" class="school-choice ${m?.value===v?'selected':''}" aria-pressed="${m?.value===v}" ${naSchool.busy?'disabled':''}>${v==='presente'?'Presente':'Ausente'}</button>`).join('')}</div>`}</article>`}).join('')}<div class="school-call-footer"><p class="help">${readOnly?'Registro preservado para consulta.':'Cada marcação só é confirmada após ser salva no servidor.'}</p>${!readOnly?schoolButton('finish','Concluir chamada',`${naSchool.busy||marked!==r.students.length?'disabled':''}`,true):''}</div></section>`}
async function loadSchool(){if(novaAuth.stage!=='ready'||page!=='school')return;try{const data=await requestShared('/api/school/day'+(naSchool.date?'?date='+encodeURIComponent(naSchool.date):''));if(novaAuth.stage!=='ready'||page!=='school')return;naSchool.data=data;naSchool.error='';schoolRender()}catch(e){naSchool.error=e.message;schoolRender();throw e}}
function schoolRender(){if(novaAuth.stage!=='ready'||page!=='school')return;shell();document.getElementById('school-history-form')?.addEventListener('submit',e=>{e.preventDefault();naSchool.date=new FormData(e.currentTarget).get('date');loadSchool().catch(e=>toast(e.message))})}
function schoolRouteForm(id){const d=naSchool.data,r=d.routes.find(r=>r.id===id)||{line:'',school:'',time:'',direction:'Ida',students:[],weekdays:[1,2,3,4,5],assignees:[]};modal(id?'Editar viagem':'Nova viagem','Uma chamada independente por horário e sentido.',field('line','Linha','text',r.line,'required maxlength="80"')+field('school','Escola / destino','text',r.school,'required maxlength="120"')+field('time','Horário','time',r.time,'required')+opsSelect('direction','Sentido',[['Ida','Ida'],['Volta','Volta']],r.direction)+`<fieldset class="full school-checks"><legend>Dias da semana</legend>${[[1,'Seg'],[2,'Ter'],[3,'Qua'],[4,'Qui'],[5,'Sex'],[6,'Sáb'],[0,'Dom']].map(([v,l])=>`<label class="check"><input type="checkbox" name="weekdays" value="${v}" ${r.weekdays.includes(v)?'checked':''}>${l}</label>`).join('')}</fieldset><fieldset class="full school-assignees"><legend>Funcionários responsáveis</legend><p class="help">Cada funcionário vê somente as viagens vinculadas à própria conta.</p>${d.employees.map(e=>`<label class="check"><input type="checkbox" name="assignees" value="${e.id}" ${r.assignees.includes(e.id)?'checked':''}>${esc(e.name)}${e.title?' · '+esc(e.title):''}</label>`).join('')}</fieldset>`+opsArea('students','Alunos — um por linha',r.students.map(s=>s.name).join('\n'),true,12000),async f=>{const students=f.get('students').split('\n').map(s=>s.trim()).filter(Boolean);const available=[...r.students];const input={line:f.get('line'),school:f.get('school'),time:f.get('time'),direction:f.get('direction'),weekdays:f.getAll('weekdays').map(Number),assignees:f.getAll('assignees'),students:students.map(name=>{const index=available.findIndex(s=>s.name===name),previous=index<0?null:available.splice(index,1)[0];return {name,...(previous?{id:previous.id}:{})}}),...(id?{version:r.version}:{})};await requestShared('/api/school/routes'+(id?'/'+id:''),{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});closeModal();await loadSchool();toast('Viagem salva na empresa.')},'Salvar viagem')}
async function schoolAction(b){if(naSchool.busy)return;const action=b.dataset.schoolAction;switch(action){case'view':naSchool.view=b.dataset.view;naSchool.trip=null;naSchool.date='';return loadSchool();case'refresh':return loadSchool();case'new':return schoolRouteForm();case'edit':return schoolRouteForm(b.dataset.route);case'archive':{const r=naSchool.data.routes.find(r=>r.id===b.dataset.route);return modal('Arquivar viagem',r.school,'<p class="full">A viagem sairá do itinerário. O histórico permanecerá disponível.</p>',async()=>{await requestShared('/api/school/routes/'+r.id+'/archive',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:r.version})});closeModal();await loadSchool()},'Arquivar viagem')}case'back':naSchool.trip=null;return loadSchool();case'open':{const result=await requestShared('/api/school/routes/'+b.dataset.route+'/start',{method:'POST'});naSchool.trip=result.trip;return schoolRender()}case'review':{naSchool.trip=(await requestShared('/api/school/trips/'+b.dataset.trip)).trip;return schoolRender()}case'mark':case'finish':{const t=naSchool.trip;naSchool.busy=true;schoolRender();try{const result=await requestShared('/api/school/trips/'+t.id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:action==='mark'?'mark':'finish',version:t.version,studentId:b.dataset.student,value:b.dataset.value})});naSchool.trip=result.trip;if(action==='finish')toast('Chamada concluída e salva.')}catch(e){if(e.status===409)try{naSchool.trip=(await requestShared('/api/school/trips/'+t.id)).trip}catch{}throw e}finally{naSchool.busy=false;schoolRender()}return}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-school-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(schoolAction(b)).catch(e=>toast(e.message))},true);
